import ua.max.tomrun.VehicleModel;import java.io.*;import javax.imageio.ImageIO;import java.awt.*;import java.awt.image.*;
public class VehicleAudit {public static void main(String[] args)throws Exception{VehicleModel m=new VehicleModel(new FileInputStream(args[0]));BufferedImage src=ImageIO.read(new File(args[1]));BufferedImage b=new BufferedImage(180,390,BufferedImage.TYPE_INT_RGB);Graphics2D g=b.createGraphics();g.drawImage(src,0,0,180,415,null);g.dispose();int[] p=b.getRGB(0,0,180,390,null,0,180);g=b.createGraphics();g.setColor(Color.RED);for(VehicleModel.Hit h:m.detect(p,180,390)){System.out.printf("%d,%d,%d,%d %.4f%n",h.x,h.y,h.w,h.h,h.score);g.drawRect(h.x,h.y,h.w,h.h);}g.dispose();ImageIO.write(b,"png",new File(args[2]));}}
